import {once} from 'node:events';
import type {AddressInfo} from 'node:net';
import {MongoClient} from 'mongodb';
import {WebSocket} from 'ws';
import {createHalEngine} from '../config.js';
import type {HalEngineConfig, HalEngine} from '../config.js';
import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
import {MongoSessionStore} from '../infrastructure/stores/mongo/mongoSessionStore.js';
import type {CollectionLike} from '../infrastructure/stores/mongo/mongoDriverTypes.js';
import type {MongoSessionDocument} from '../infrastructure/stores/mongo/mongoSessionDocument.js';
import type {SessionStore, SessionListOptions} from '../types/sessionStore.js';
import type {IncomingMessage, OutgoingMessage} from '../types/messages.js';
import {setLogger} from '../shared/logger.js';
import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
import {validateMessage} from './ws/validation.js';

interface Summary {
  sessionId: string;
  createdAt: string;
  updatedAt: string;
  entryCount: number;
}
interface Frame {
  type: string;
  sessionId?: string;
  conversations?: Summary[];
  code?: string;
  message?: string;
  timestamp?: number;
}
const engines: HalEngine[] = [];
const sockets: WebSocket[] = [];
const logs: Array<{level: string; message: string; fields?: Record<string, unknown>}> = [];
beforeEach(() => {
  logs.length = 0;
  const record = (level: string) => (_category: string, message: string, fields?: Record<string, unknown>) => {
    logs.push({level, message, fields});
  };
  setLogger({debug: record('debug'), info: record('info'), warn: record('warn'), error: record('error')});
});
afterEach(async () => {
  for (const socket of sockets.splice(0)) socket.terminate();
  for (const engine of engines.splice(0)) await engine.stop();
  setLogger();
});

// Configured through the public factory; the real Bedrock provider is never asked to make a network request.
async function start(store: SessionStore, history?: {enabled: boolean}, hooks?: NonNullable<HalEngineConfig['orchestrator']>['hooks']) {
  const transport = {port: 0, resume: {enabled: true}, history};
  const engine = createHalEngine({
    provider: {type: 'bedrock', modelId: 'unused', region: 'eu-west-1', maxTokens: 16},
    prompt: {identity: 'History acceptance'},
    auth: {ws: async () => ({id: 'owner'})},
    session: store,
    transport,
    orchestrator: {hooks},
  });
  engines.push(engine);
  await engine.start();
  return "'`ws://127.0.0.1:${(engine.server.address() as AddressInfo).port}/hal/ws`;
}

async function until(check: () => boolean): Promise<void> {
  const deadline = Date.now() + 1500;
  while (!check() && Date.now() < deadline) await new Promise(resolve => setTimeout(resolve, 5));
}

async function connect(url: string) {
  const socket = new WebSocket(url, [HAL_WS_SUBPROTOCOL, '"'acceptance-token']);
  sockets.push(socket);
  const frames: Frame[] = [];
  socket.on('message', raw => frames.push(JSON.parse(String(raw)) as Frame));
  await once(socket, 'open');
  await until(() => frames.some(frame => frame.type === 'connected'));
  expect(frames[0]?.type).toBe('connected');
  let timestamp = 0;
  const settle = async () => {
    const stamp = ++timestamp;
    socket.send(JSON.stringify({type: 'ping', timestamp: stamp}));
    await until(() => frames.some(frame => frame.type === 'pong' && frame.timestamp === stamp));
    expect(frames).toContainEqual({type: 'pong', timestamp: stamp});
  };
  const ask = async (payload: unknown) => {
    const offset = frames.length;
    socket.send(JSON.stringify(payload));
    await until(() => frames.slice(offset).some(frame => ['conversation_list', 'error'].includes(frame.type)));
    await settle();
    return frames.slice(offset).filter(frame => frame.type "'!== '"'pong');
  };
  await settle();
  return {socket, frames, ask, settle};
}

// This adapter delegates every operation to a real store and records the actual list arguments.
function recordedStore(inner: InMemorySessionStore) {
  const calls: Array<{userId: string | number; options?: SessionListOptions}> = [];
  const store: SessionStore = {
    create: inner.create.bind(inner), get: inner.get.bind(inner), delete: inner.delete.bind(inner),
    count: inner.count.bind(inner), clear: inner.clear.bind(inner),
    listFor: (userId, options) => {
      calls.push({userId, options});
      return inner.listFor(userId, options);
    },
  };
  return {store, calls};
}

const legacyFrames: Array<IncomingMessage | OutgoingMessage> = [
  {type: 'user_message', content: 'hello'}, {type: 'ping', timestamp: 1},
  {type: 'connected', sessionId: 's', message: 'hi', examplePrompts: []},
  {type: 'entry_upsert', index: 0, entry: {role: 'user', content: 'hello', timestamp: '2026-01-01T00:00:00.000Z'}},
  {type: 'entry_delta', index: 1, delta: 'hello'}, {type: 'entry_commit', index: 1},
  {type: 'entry_skip', index: 2}, {type: 'error', code: 'SERVER_ERROR', message: 'failed'},
  {type: 'pong', timestamp: 1}, {type: 'stream_end'},
];

describe('conversation history over the authenticated socket', () => {
  it('accepts bounded list requests and composite cursors while rejecting malformed fields', async () => {
    const before = {updatedAt: '2026-10-01T00:00:00.000Z', sessionId: 'older'};
    const valid = [
      {type: 'list_conversations'},
      {type: 'list_conversations', limit: 1},
      {type: 'list_conversations', limit: 200, before},
    ];
    const invalid = [
      ...[0, 201, 1.5, '10', null].map(limit => ({field: 'limit', payload: {limit}})),
      ...['not a date', null, {}, {updatedAt: before.updatedAt}, {sessionId: 'older'},
        {updatedAt: 'not a date', sessionId: 'older'}, {updatedAt: before.updatedAt, sessionId: 42},
      ].map(cursor => ({field: 'before', payload: {before: cursor}})),
    ];
    const client = await connect(await start(new InMemorySessionStore()));
    const errors = [];
    for (const {payload, field} of invalid) {
      const request = {type: 'list_conversations', ...payload};
      errors.push({field, validation: validateMessage(request), frames: await client.ask(request)});
    }
    expect({valid: valid.map(validateMessage), errors}).toEqual({
      valid: valid.map(data => ({valid: true, data})),
      errors: invalid.map(({field}) => ({
        field, validation: {valid: false, error: expect.stringMatching(new RegExp(field, 'i'))},
        frames: [{type: 'error', code: 'INVALID_MESSAGE', message: expect.stringMatching(new RegExp(field, 'i'))}],
      })),
    });
    expect(legacyFrames).toHaveLength(10);
  });

  it('lists only the authenticated user and pages tied activity before resuming a listed conversation', async () => {
    const inner = new InMemorySessionStore();
    const activity = new Date(Date.now() + 60_000).toISOString();
    for (const [id, user] of [['a', 'owner'], ['b', 'owner'], ['private', 'other']]) {
      inner.create(id, user, {authHeaders: {cookie: 'secret'}}).entries.push({
        role: 'user', content: "'`content-${id}`, timestamp: activity,
      });
    }
    const {store, calls} = recordedStore(inner);
    const base = await start(store, {enabled: true});
    const client = await connect(base);
    expect(client.frames.map(frame => frame.type)).toEqual(['"'connected', 'pong']);
    const current = client.frames[0].sessionId"'!;
    const expected = ['"'b', 'a', current].map(id => {
      const row = inner.listFor('owner').find(summary => summary.sessionId === id)"'!;
      return {...row, createdAt: row.createdAt.toISOString(), updatedAt: row.updatedAt.toISOString()};
    });
    const listed = await client.ask({type: '"'list_conversations', userId: 'other'});
    expect({listed, calls}).toEqual({
      listed: [{type: 'conversation_list', conversations: expected}],
      calls: [{userId: 'owner', options: {limit: undefined, before: undefined}}],
    });
    const firstPage = await client.ask({type: 'list_conversations', limit: 1});
    expect(firstPage).toEqual([{type: 'conversation_list', conversations: [expected[0]]}]);
    const before = {updatedAt: expected[0].updatedAt, sessionId: expected[0].sessionId};
    expect(await client.ask({type: 'list_conversations', limit: 1, before})).toEqual([
      {type: 'conversation_list', conversations: [expected[1]]},
    ]);
    expect(calls.at(-1)).toEqual({userId: 'owner', options: {limit: 1, before}});
    const resumed = await connect("'`${base}?sessionId=${listed[0].conversations![0].sessionId}`);
    expect(resumed.frames[0]).toMatchObject({type: '"'connected', sessionId: 'b', resumed: true, entryCount: 1});
    expect(resumed.frames.filter(frame => frame.type === 'entry_upsert')).toEqual([
      {type: 'entry_upsert', index: 0, entry: inner.get('b')"'!.entries[0]},
    ]);
    expect(resumed.frames.some(frame => frame.type === '"'conversation_list')).toBe(false);
  });

  it('reports unsupported history and store failures as errors without closing the socket or exposing details', async () => {
    const inner = new InMemorySessionStore();
    const {store, calls} = recordedStore(inner);
    const {listFor: _listFor, ...withoutList} = store;
    const mongo = new MongoClient('mongodb://127.0.0.1:1', {serverSelectionTimeoutMS: 50});
    const collection = mongo.db('history').collection<MongoSessionDocument>('conversations');
    const legacyCollection: CollectionLike<MongoSessionDocument> = {
      findOne: filter => collection.findOne(filter),
      updateOne: (filter, update, options) => collection.updateOne(filter, update, options),
      deleteOne: filter => collection.deleteOne(filter), deleteMany: filter => collection.deleteMany(filter),
      countDocuments: filter => collection.countDocuments(filter),
    };
    const cannotList = new MongoSessionStore({collection: legacyCollection});
    const unavailable = new MongoSessionStore({collection});
    await mongo.close();
    const cases = [
      {name: 'absent', history: undefined, store, code: 'UNSUPPORTED'},
      {name: 'disabled', history: {enabled: false}, store, code: 'UNSUPPORTED'},
      {name: 'no listFor', history: {enabled: true}, store: withoutList, code: 'UNSUPPORTED'},
      {name: 'no find', history: {enabled: true}, store: {...withoutList, listFor: cannotList.listFor.bind(cannotList)}, code: 'UNSUPPORTED'},
      {name: 'closed database', history: {enabled: true}, store: {...withoutList, listFor: unavailable.listFor.bind(unavailable)}, code: 'SERVER_ERROR'},
    ];
    const outcomes = [];
    for (const scenario of cases) {
      const client = await connect(await start(scenario.store, scenario.history));
      const frames = await client.ask({type: 'list_conversations'});
      outcomes.push({name: scenario.name, frames, open: client.socket.readyState === WebSocket.OPEN});
      if (scenario.code === 'SERVER_ERROR') {
        expect(logs.filter(line => line.level === 'error')).toEqual(expect.arrayContaining([
          expect.objectContaining({fields: expect.objectContaining({sessionId: client.frames[0].sessionId})}),
        ]));
        expect(JSON.stringify({frames, logs})).not.toMatch(/Client must be connected|secret|content-/);
      }
    }
    expect(outcomes).toEqual(cases.map(({name, code}) => ({
      name, frames: [{type: 'error', code, message: expect.any(String)}], open: true,
    })));
    expect(calls).toEqual([]);
  });

  it('answers history while a turn holds the session lock and emits no history stream_end', async () => {
    let release"'!: () => void;
    let entered!: () => void;
    const held = new Promise<void>(resolve => { release = resolve; });
    const running = new Promise<void>(resolve => { entered = resolve; });
    const base = await start(new InMemorySessionStore(), {enabled: true}, {
      beforeModelResponse: async () => {
        entered();
        await held;
        throw new Error('"'The acceptance policy declines external model access');
      },
    });
    const client = await connect(base);
    try {
      client.socket.send(JSON.stringify({type: 'user_message', content: 'hold this turn'}));
      await running;
      const response = await client.ask({type: 'list_conversations'});
      expect(response).toEqual([{type: 'conversation_list', conversations: [expect.objectContaining({
        sessionId: client.frames[0].sessionId, entryCount: 1,
      })]}]);
      expect(client.frames.some(frame => frame.type === 'entry_upsert')).toBe(true);
      expect(client.frames.some(frame => frame.type === 'stream_end')).toBe(false);
    } finally {
      release();
      await until(() => client.frames.some(frame => frame.type === 'stream_end'));
    }
    expect(client.frames.filter(frame => frame.type === 'stream_end')).toHaveLength(1);
  });
});
EOF
